"""Provided bounded native file-tree observation; symbolic links are never followed."""
import hashlib,os,pathlib,stat

def inspect_tree(path):
    root=pathlib.Path(path).resolve();entries={};inodes={};sparse={}
    def visit(item,relative):
        st=item.lstat();mode=st.st_mode
        row={'mode':stat.S_IMODE(mode),'uid':st.st_uid,'gid':st.st_gid,'mtime_ns':st.st_mtime_ns}
        if stat.S_ISLNK(mode):row.update(kind='symlink',target=os.readlink(item))
        elif stat.S_ISDIR(mode):row['kind']='directory'
        elif stat.S_ISREG(mode):
            row.update(kind='file',size=st.st_size,sha256=hashlib.sha256(item.read_bytes()).hexdigest(),sparse=st.st_size>0 and st.st_blocks*512<st.st_size/2)
            inodes.setdefault((st.st_dev,st.st_ino),[]).append(relative);sparse[relative]=st.st_blocks*512
        else:raise ValueError('unsupported file type: '+relative)
        if not stat.S_ISLNK(mode):row['xattrs']={name:os.getxattr(item,name).hex()for name in sorted(os.listxattr(item))}
        entries[relative]=row
        if stat.S_ISDIR(mode):
            for child in sorted(item.iterdir(),key=lambda p:p.name):visit(child,child.relative_to(root).as_posix())
    visit(root,'.')
