    groups=sorted(sorted(paths)for paths in inodes.values()if len(paths)>1)
    normalized={'entries':entries,'hardlink_groups':groups};encoded=__import__('json').dumps(normalized,sort_keys=True,separators=(',',':')).encode();vfs=os.statvfs(root)
