import pathlib,shutil,subprocess,time

def migrate(source,destination,observe):
    if not callable(observe):raise ValueError('native observer must be callable')
    source=pathlib.Path(source).resolve();destination=pathlib.Path(destination).resolve()
    if source==destination or source in destination.parents or destination in source.parents:raise ValueError('overlapping roots')
    if not source.is_dir()or not destination.is_dir():raise ValueError('existing owned directories required')
    before=observe(source);observe(destination)
    # Destination is an owned, inactive staging tree. Source remains the rollback copy.
    started=time.monotonic_ns()
    for entry in destination.iterdir():
        if entry.is_symlink()or not entry.is_dir():entry.unlink()
        else:shutil.rmtree(entry)
    subprocess.run(['cp','-a','--sparse=always','--',str(source)+'/.',str(destination)+'/'],check=True,capture_output=True)
    source_after=observe(source);target_after=observe(destination)
    if before['manifest']!=source_after['manifest']or source_after['manifest']!=target_after['manifest']:raise ValueError('source drift or copy mismatch')
    return {'schema':1,'source_before':before,'source_after':source_after,'target_after':target_after,'elapsed_ns':time.monotonic_ns()-started,'old_source_retained':True,'covered_types':['directory','file','hardlink','sparse','symlink'],'uncovered_types':['block_device','fifo','socket'],'scope':'owned_quiesced_subtree_not_mounted_volume_cutover'}

